export function preparationMarkup(){return `<section class="preparation flow-page"><div class="eyebrow">Preparing your report</div><h1>Your answers, brought together.</h1><p>We’re bringing your five dimensions into focus.</p><div class="report-illustration" aria-hidden="true"><div class="paper paper-back"></div><div class="paper paper-front"><span class="mini-report-leaf">✳</span><div class="mini-bars"><i></i><i></i><i></i><i></i><i></i></div><div class="mini-orbit"></div><div class="mini-lines"><i></i><i></i></div></div><span class="report-spark spark-one">✧</span><span class="report-spark spark-two">✧</span></div><ol class="preparation-steps"><li id="prepare-scores">Calculate five dimensions</li><li id="prepare-graphs">Prepare your graphs</li><li id="prepare-save">Save your report</li></ol><p id="prepare-status" role="status" aria-live="polite"></p><button class="primary" id="preparation-continue" disabled>Continue →</button></section>`}
export function emailDraft({email,profile,scores,traits,language='en',url}){if(!/^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(email))throw new Error('Enter a valid email address.');const hi=language==='hi',subject=hi?'मेरी Innerly रिपोर्ट':'My Innerly personality report',body=[hi?'मेरी व्यक्तित्व रिपोर्ट':'My personality reflection',profile.title,profile.summary,'',...traits.map((trait,i)=>`${trait.name}: ${scores[i]} / 100`),'',hi?'खुद को समझने के लिए। क्लिनिकल जाँच नहीं।':'For self-reflection. Not a clinical assessment.',url].join('\n');return `mailto:${encodeURIComponent(email)}?subject=${encodeURIComponent(subject)}&body=${encodeURIComponent(body)}`}
